function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 letters.';
  if (!/^[A-Z]+$/.test(s)) return 's may contain only uppercase English letters.';
  return null;
}

