function uniqueLetterString(s) {
  const n = s.length;
  const previous = new Array(n);
  const next = new Array(n);
  const lastSeen = new Map();
  for (let i = 0; i < n; i++) {
    previous[i] = lastSeen.has(s[i]) ? lastSeen.get(s[i]) : -1;
    lastSeen.set(s[i], i);
  }
  lastSeen.clear();
  for (let i = n - 1; i >= 0; i--) {
    next[i] = lastSeen.has(s[i]) ? lastSeen.get(s[i]) : n;
    lastSeen.set(s[i], i);
  }
  let total = 0;
  for (let i = 0; i < n; i++) {
    total += (i - previous[i]) * (next[i] - i);
  }
  return total;
}

