function uniqueLetterString(s) {
  // Grow every substring from each start, keeping letter counts and how many letters occur exactly once.
  let sum = 0;
  for (let start = 0; start < s.length; start++) {
    const counts = new Array(26).fill(0);
    let once = 0;
    for (let end = start; end < s.length; end++) {
      const c = s.charCodeAt(end) - 65;
      counts[c]++;
      if (counts[c] === 1) once++;
      else if (counts[c] === 2) once--;
      sum += once;
    }
  }
  return sum;
}

