function generate(rand, size) {
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.slice(0, 1 + Math.floor(rand() * (size === 'large' ? 26 : 5)));
  const n = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 15);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * letters.length)];
  return [s];
}
